import{_ as o,l,o as e,c as i,v as t,p as A,x as r,d as p,i as s,S as c}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"资产增长异常","description":"","frontmatter":{"title":"资产增长异常","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/asset-growth.md","filePath":"quant/asset-growth.md","lastUpdated":1789023840000}'),h={name:"quant/asset-growth.md"};function E(d,a,m,u,C,B){const n=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="资产增长异常" tabindex="-1">资产增长异常 <a class="header-anchor" href="#资产增长异常" aria-label="Permalink to &quot;资产增长异常&quot;">​</a></h1><div class="epigraph"><p>总资产增长率最高的公司，随后截面收益显著更低；这一模式覆盖资本开支、并购、存货与营运资本，不能单用市场 β 解释。</p><footer>—— Cooper, Gulen &amp; Schill, Asset Growth and the Cross-Section of Stock Returns, Journal of Finance, 2008</footer></div><p><a href="/quant/investment-factor">投资与资产增长</a> 一文以 CMA、q 理论与 capex 对照为主。本篇回到 Cooper、Gulen、Schill 2008 年的异常本身：排序键是总资产增长率 \\(\\Delta A_t/A_{t-1}\\)，主张它比单一资本开支更单调、更宽。Fama–French 后来把低减高做成 CMA，组合定义与 2×3 权重并不等于 CGS 的十分位等权。读本文是为了复制 2008 年的分解，并把它和<a href="/quant/accruals-anomaly">应计</a>、<a href="/quant/net-issuance">净发行</a> 放在同一张资产负债表上，而不是再讲一遍五因子构造。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>股利贴现与 q 理论都暗示：给定当前市值，预期投资高则内部收益率低，事后收益应低。投资的观测有窄有宽。窄的是 capex/销售或 capex/资产（Titman–Wei–Xie）；宽的是总资产增长，含收购、应收、存货、现金、商誉。CGS 的问题是：哪一个会计增长对收益的排序最干净？若总资产赢了，机制就不能只讲「建厂过多」，还要能讲并购与营运资本。</p><p>三因子用 B/M 间接抓了一部分：高投资压低未来账面市值比、抬高当期估值。CGS 报告在控制 B/M、规模、动量之后总资产增长仍预测负收益，故不是纯价值、纯动量。需要进一步问：控制应计与净发行之后还剩多少——因为营运资本应计和发股扩张是 \\(\\Delta A\\) 的组件。</p><h3 id="为什么总资产比-capex-更「宽」也更「脏」" tabindex="-1">为什么总资产比 capex 更「宽」也更「脏」 <a class="header-anchor" href="#为什么总资产比-capex-更「宽」也更「脏」" aria-label="Permalink to &quot;为什么总资产比 capex 更「宽」也更「脏」&quot;">​</a></h3> \\[\\mathrm{AG}_t=\\frac{A_t-A_{t-1}}{A_{t-1}} \\]<p>分子可以拆成流动资产、长期经营资产、现金、以及其他。CGS 发现多个组件都带负号，不只是 PP&amp;E。这支持「扩张这一类行为」被错误定价或被贴现，而不是某个科目的会计怪癖。代价是解释权分散：现金堆积不像帝国建造；商誉跳跃是并购溢价。CMA 沿用总资产口径，空头腿因此含收购机器。若产品故事是「反对乱并购」，应直接用并购指示变量，而不是默认 AG 十分位。</p><p><span class="marginnote">HML 的空头是低 B/M；AG 的空头是高增长。两者经常重叠（成长公司爱扩张），不是恒等。低 B/M 且不扩张、高 B/M 且猛扩张的格子，才是价值和投资分开的证据。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每年用已公布年报算 AG，滞后对齐到 6 月，NYSE 断点，等权与价值加权都要报。CGS 主结果对等权更强，价值加权仍在但更薄——与应计类似的容量结构。持有一年。稳健性：按规模分层、按 B/M 分层、剔除金融、缩尾极端并购。分解回归：把 AG 换成各组件，或在 Fama–MacBeth 里同时放 AG、应计、净发行、NOA 增长。</p><p>与 CMA 对齐：CMA 是规模 2×3、价值加权、低减高；CGS 常是十分位对冲。同一数据上两条腿相关高，α 的 t 值不能互相当独立样本。复制五因子用 CMA；复制 2008 年论文用 AG 十分位，并声明加权。</p><h3 id="组件分解是论文的心脏" tabindex="-1">组件分解是论文的心脏 <a class="header-anchor" href="#组件分解是论文的心脏" aria-label="Permalink to &quot;组件分解是论文的心脏&quot;">​</a></h3><p>把 \\(\\Delta A\\) 拆成：现金、非现金流动资产、PP&amp;E、其他长期资产（含商誉）。再从融资边拆：留存收益、净发行、净债务。经营资产增长与净发行往往都预测负收益；现金增长更弱或视估值而定。这一张分解表决定你站哪条机制：若只有 PP&amp;E 显著，像 capex 异常；若应收存货也显著，像应计；若只有净发行显著，AG 只是融资的马甲。原文的主张是多组件同时工作，因而总资产是便捷的充分统计量。</p>',15)),(e(),A(c,null,{default:r(()=>[s(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20AG%5B%22%E6%80%BB%E8%B5%84%E4%BA%A7%E5%A2%9E%E9%95%BF%E7%8E%87%22%5D%20--%3E%20SORT%5B%22%E5%88%86%E4%BD%8D%E5%A4%9A%E7%A9%BA%EF%BC%88%E7%AD%89%E6%9D%83%2F%E5%80%BC%E6%9D%83%EF%BC%89%22%5D%0A%20%20PPE%5B%22PP%26E%20%2F%20capex%22%5D%20--%3E%20AG%0A%20%20WC%5B%22%E8%90%A5%E8%BF%90%E8%B5%84%E6%9C%AC%22%5D%20--%3E%20AG%0A%20%20MNA%5B%22%E5%B9%B6%E8%B4%AD%E4%B8%8E%E5%95%86%E8%AA%89%22%5D%20--%3E%20AG%0A%20%20CASH%5B%22%E7%8E%B0%E9%87%91%22%5D%20--%3E%20AG%0A%20%20NI%5B%22%E5%87%80%E5%8F%91%E8%A1%8C%22%5D%20--%3E%20FIN%5B%22%E8%9E%8D%E8%B5%84%E8%BE%B9%22%5D%0A%20%20AG%20--%3E%20FIN%0A%20%20SORT%20--%3E%20CTR%5B%22%E6%8E%A7%E5%88%B6%20B%2FM%E3%80%81%E5%BA%94%E8%AE%A1%E3%80%81%E5%8F%91%E8%A1%8C%22%5D%0A%20%20FIN%20--%3E%20CTR%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>q 理论：低风险溢价 → 高边际 q → 高投资 → 低后续收益。预测宏观上投资高的年份市场随后也弱，微观上 AG 与事后收益负相关。代理：自由现金流充裕时经理扩张，NPV 为负的项目随后被证伪。会计：扩张抬高当期应计与未来折旧，投资者对盈利水平反应不足，于是 AG 像「未来失望」的代理。三条在 CGS 样本里分不开，但对冲不同：贴现率冲击、治理、盈余公告。</p><p>与动量的时间冲突：赢家里有一批刚完成扩张叙事的公司，AG 空头与 WML 多头短期打架。与价值：价值股往往少扩张，CMA/AG 与 HML 正相关。危机后 capex 冰冻，低 AG 多头拥挤，一旦资本开支周期重启，异常回撤。换手低（年度财务）不代表经济暴露平滑。</p><h3 id="发表后与五因子时代" tabindex="-1">发表后与五因子时代 <a class="header-anchor" href="#发表后与五因子时代" aria-label="Permalink to &quot;发表后与五因子时代&quot;">​</a></h3><p>CMA 把 AG 写进标准模型之后，再报一个「资产增长 α」而不对 CMA 正交，没有信息。剩余问题变成：十分位等权 AG 在大盘价值加权 CMA 之外还有没有可交易的一块？若只存在于微型盘并购，则 2008 年表格的经济意义要降级。q 因子同样用投资，对 AG 的吸收更直接。应把 CGS 异常当成发现投资定价的关键证据，而不是永远独立于 CMA 的第七个因子。</p><p><span class="marginnote">长期反转是价格路径；AG 是资产负债表路径。控制过去三年收益后 AG 仍常显著，故不要把本文写成 De Bondt–Thaler 的会计版。反之，价格大跌本身会通过市值而非资产改变 B/M，两条腿仍应分开。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>前视：用未公布年报的期末资产会造假溢价。季度资产加快信号，季节性与并购确认时点变噪。跨国：IFRS 商誉与并购会计切换会打断 AG 序列。A 股借壳、重组可让总资产一年翻数倍，等权空头被少数点主导，必须缩尾或单独分组。金融业资产即产品，默认剔除。</p><p>不要把高 capex 的基本面故事翻成正的预期收益——截面符号是负的。不要把 CMA、capex 多空、AG 十分位三条一起放进回归当三个 α。容量：大盘价值加权可交易；等权高 AG 空头含不可借券的收购机器。与应计、净发行的重叠见各自专文，实施时选一个主键。</p><p><span class="marginnote">出处：Cooper, Gulen &amp; Schill, <em>Journal of Finance</em>, 2008。capex 异常见 Titman, Wei &amp; Xie, 2004。CMA 见 Fama &amp; French, 2015；q 因子见 Hou, Xue &amp; Zhang, 2015。构造对照见<a href="/quant/investment-factor">投资与资产增长</a>。不要把 CMA 的 2×3 定义写进 2008 年论文。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>高总资产增长预测低收益，组件宽于 capex，含并购与营运资本。</li><li>等权强于价值加权；与 CMA 同向但组合定义不同，不能并列为两个 α。</li><li>须控制价值、应计与净发行，并检查微型盘并购是否驱动空头。</li><li>机制可以是 q、代理或盈利失望；换手低并不等于路径平滑。</li><li>出处：Cooper, Gulen &amp; Schill, Journal of Finance, 2008。</li></ul>',12))])}const f=o(h,[["render",E]]);export{_ as __pageData,f as default};
